import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { api, post } from '../../lib/api';
import { Card, ErrorNote, Head, Pill } from '../../components/ui';
import { useUi } from '../../lib/store';

const tabs=['Board','Work Orders','Line','Handover','Tool Crib','Shops','AOG','Stations'] as const;
type Tab=(typeof tabs)[number];
const tone=(s:string):any=>['COMPLETE','RELEASED','DEPARTED','AVAILABLE','ACCEPTED','CLOSED','RTS','ACTIVE'].includes(s)?'green':['HOLD','IN_PROGRESS','QUARANTINE','RECOVERY','MATERIAL'].includes(s)?'amber':['AOG','CRITICAL','LOST','DAMAGED','SCRAPPED','CANCELLED','SUSPENDED'].includes(s)?'red':'cyan';
const zulu=(v?:string|null)=>v?new Date(v).toISOString().replace('.000',''):'—';
const refresh=(qc:any)=>{void qc.invalidateQueries({queryKey:['mnt']});};

type WO={id:string;orderType:string;tail:string|null;componentRef:string|null;station:string;aircraftType:string|null;title:string;priority:string;status:string;plannedStart:string|null;plannedEnd:string|null;plannedHours:number;actualMinutes:number;holdReason:string|null;contractId:string|null;slaDueAt:string|null;customerApprovalRef:string|null;customerRef:string|null};
type LV={id:string;tail:string;aircraftType:string;station:string;inboundFlight:string|null;outboundFlight:string|null;scheduledIn:string;scheduledOut:string;status:string;workOrderId:string|null;openDefects:number;deferredDefectRefs:string[];turnaroundNotes:string|null};
type HItem={id:string;itemType:string;reference:string;description:string;priority:string;status:string;resolution:string|null};
type H={id:string;station:string;workArea:string;outgoingShift:string;incomingShift:string;handedOverBy:string;handedOverAt:string;status:string;summary:string;items:HItem[]};
type Tool={id:string;toolNo:string;serial:string|null;description:string;station:string;crib:string;kitCode:string|null;calibrationRequired:boolean;calibratedUntil:string|null;certificateRef:string|null;status:string};
type Finding={id:string;finding:string;status:string};
type Shop={id:string;shopType:string;partNo:string;serial:string;workscope:string;status:string;plannedRelease:string|null;findings:Finding[]};
type Aog={id:string;tail:string;station:string;defectRef:string;severity:string;status:string;technicalSummary:string;recoveryEta:string|null;requiredPart:string|null;logisticsRef:string|null;estimatedCostMinor:number;currency:string;updates:{id:string;updateType:string;note:string;createdAt:string}[]};
type Cap={id:string;station:string;aircraftType:string;maintenanceLevel:string;scope:string[];authorityRef:string;minimumAuthorizedStaff:number;requiredToolNos:string[];facilities:string[];effectiveFrom:string;effectiveUntil:string|null;active:boolean};

type Assignment={id:string;personnelId:string;assignmentRole:string;trade:string|null;shiftRef:string|null;plannedMinutes:number;actualMinutes:number;releasedAt:string|null};
type Person={id:string;name:string;roleTitle:string|null;authorised:boolean};
type Outsource={id:string;vendor_ref:string;scope:string;status:string;due_at:string|null;return_release_ref:string|null};
type Progress={id:string;customer_ref:string;percent_complete:number;forecast_release:string|null;tat_variance_minutes:number|null;summary:string;sent_at:string};
type Contract={id:string;customerRef:string;contractRef:string;stationScope:string[];aircraftTypes:string[];maintenanceLevels:string[];responseSlaMinutes:number|null;tatSlaHours:number|null;active:boolean};
type Reservation={id:string;toolId:string;workOrderId:string|null;taskCardId:string|null;reservedFrom:string;reservedUntil:string;status:string};
type PiecePart={id:string;partNo:string;serial:string|null;lotNo:string|null;incomingCondition:string;disposition:string;repairSchemeRef:string|null;externalOrderRef:string|null;traceRef:string|null;installed:boolean};
type MaterialKitItem={id:string;partNo:string;description:string|null;qtyRequired:number;qtyPicked:number;stockRef:string|null;certificateRef:string|null};
type MaterialKit={id:string;workOrderId:string|null;wpId:string|null;kitNo:string;station:string;status:string;items:MaterialKitItem[]};
type Dash={counts:{workOrdersOpen:number;lineVisitsActive:number;aogOpen:number;handoversOpen:number;toolsUnavailable:number;shopOpen:number};workOrders:WO[];lineVisits:LV[];aog:Aog[]};

export function MaintenanceControl(){const [tab,setTab]=useState<Tab>('Board');const [station,setStation]=useState('');return <><Head crumb="Maintenance" title="Maintenance Control" desc="One operational workspace for line, base, shops, tooling, handover and AOG. Actions remain inside their maintenance objects rather than becoming navigation entries."/><div className="row" style={{marginBottom:10,flexWrap:'wrap'}}><input className="inp mono" style={{width:120}} placeholder="Station" maxLength={4} value={station} onChange={e=>setStation(e.target.value.toUpperCase())}/>{tabs.map(t=><button key={t} className={`btn sm ${tab===t?'pri':''}`} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Board'&&<Board station={station}/>} {tab==='Work Orders'&&<WorkOrders station={station}/>} {tab==='Line'&&<Line station={station}/>} {tab==='Handover'&&<Handovers station={station}/>} {tab==='Tool Crib'&&<Tools station={station}/>} {tab==='Shops'&&<Shops/>} {tab==='AOG'&&<AogCases/>} {tab==='Stations'&&<Stations station={station}/>}</>}

function Board({station}:{station:string}){const q=useQuery({queryKey:['mnt','dash',station],queryFn:()=>api<Dash>(`/amo/maintenance/dashboard${station?`?station=${station}`:''}`),refetchInterval:30000});const d=q.data;return <div className="stack"><div className="kpis">{[['Open work orders',d?.counts.workOrdersOpen??0,'cyan'],['Active line visits',d?.counts.lineVisitsActive??0,'green'],['AOG',d?.counts.aogOpen??0,'red'],['Handovers',d?.counts.handoversOpen??0,'amber'],['Unavailable tools',d?.counts.toolsUnavailable??0,'amber'],['Shop orders',d?.counts.shopOpen??0,'cyan']].map(([l,v,t])=><div key={String(l)} className={`kpi ${t}`}><div className="l">{l}</div><div className="v">{v}</div></div>)}</div><Card title="Production attention"><table className="t"><thead><tr><th>Order</th><th>Subject</th><th>Station</th><th>Status</th><th>Window</th></tr></thead><tbody>{(d?.workOrders??[]).filter(x=>!['COMPLETE','CANCELLED'].includes(x.status)).slice(0,20).map(w=><tr key={w.id}><td className="mono">{w.id}<div className="sub">{w.title}</div></td><td>{w.tail??w.componentRef}</td><td>{w.station}</td><td><Pill tone={tone(w.status)}>{w.status}</Pill></td><td>{zulu(w.plannedStart)} → {zulu(w.plannedEnd)}</td></tr>)}</tbody></table></Card><Card title="Line / AOG"><div className="two-col"><div>{(d?.lineVisits??[]).filter(x=>!['DEPARTED','CANCELLED'].includes(x.status)).map(v=><div className="block" key={v.id}><b className="mono">{v.tail}</b> · {v.station} <Pill tone={tone(v.status)}>{v.status}</Pill><div className="sub">{v.inboundFlight??'—'} → {v.outboundFlight??'—'} · defects {v.openDefects}</div></div>)}</div><div>{(d?.aog??[]).map(a=><div className="block" key={a.id}><b className="mono">{a.id} · {a.tail}</b> <Pill tone="red">{a.status}</Pill><div>{a.technicalSummary}</div><div className="sub">ETA {zulu(a.recoveryEta)}</div></div>)}</div></div></Card><ErrorNote error={q.error}/></div>}

function WorkOrders({station}:{station:string}){
  const qc=useQueryClient(),toast=useUi(s=>s.toast);
  const q=useQuery({queryKey:['mnt','wo',station],queryFn:()=>api<WO[]>(`/amo/maintenance/work-orders${station?`?station=${station}`:''}`)});
  const contracts=useQuery({queryKey:['mnt','contracts'],queryFn:()=>api<Contract[]>('/amo/maintenance/contracts')});
  const [selected,setSelected]=useState<string|null>(null);
  const [f,setF]=useState({orderType:'LINE',tail:'',componentRef:'',station:station||'ENGM',aircraftType:'A320',title:'',priority:'NORMAL',customerRef:'',contractId:'',customerApprovalRef:'',plannedStart:'',plannedEnd:'',plannedHours:'0'});
  const [reasons,setReasons]=useState<Record<string,string>>({});
  const create=useMutation({mutationFn:()=>post('/amo/maintenance/work-orders',{...f,tail:f.tail||null,componentRef:f.componentRef||null,aircraftType:f.aircraftType||null,customerRef:f.customerRef||null,contractId:f.contractId||null,customerApprovalRef:f.customerApprovalRef||null,plannedStart:f.plannedStart?new Date(f.plannedStart).toISOString():null,plannedEnd:f.plannedEnd?new Date(f.plannedEnd).toISOString():null,plannedHours:Number(f.plannedHours),taskCardIds:[]}),onSuccess:()=>{toast('Work order created','green');setF(x=>({...x,title:'',tail:'',componentRef:''}));refresh(qc)}});
  const st=useMutation({mutationFn:(x:{id:string,state:string})=>post(`/amo/maintenance/work-orders/${x.id}/state`,{state:x.state,reason:reasons[x.id]||null}),onSuccess:()=>refresh(qc)});
  const next=(s:string)=>({DRAFT:['PLANNED','CANCELLED'],PLANNED:['RELEASED','CANCELLED'],RELEASED:['IN_PROGRESS','CANCELLED'],IN_PROGRESS:['HOLD','COMPLETE'],HOLD:['IN_PROGRESS','CANCELLED']} as Record<string,string[]>)[s]??[];
  return <div className="stack">
    <Card title="Create work order"><div className="form-grid"><select className="inp" value={f.orderType} onChange={e=>setF({...f,orderType:e.target.value})}>{['LINE','BASE','AOG','COMPONENT','ENGINE','MODIFICATION','UNSCHEDULED'].map(x=><option key={x}>{x}</option>)}</select><input className="inp mono" placeholder="Tail" value={f.tail} onChange={e=>setF({...f,tail:e.target.value.toUpperCase()})}/><input className="inp mono" placeholder="Component ref" value={f.componentRef} onChange={e=>setF({...f,componentRef:e.target.value})}/><input className="inp mono" maxLength={4} value={f.station} onChange={e=>setF({...f,station:e.target.value.toUpperCase()})}/><input className="inp" placeholder="Aircraft type" value={f.aircraftType} onChange={e=>setF({...f,aircraftType:e.target.value.toUpperCase()})}/><input className="inp" placeholder="Scope/title" value={f.title} onChange={e=>setF({...f,title:e.target.value})}/><select className="inp" value={f.priority} onChange={e=>setF({...f,priority:e.target.value})}>{['NORMAL','HIGH','AOG'].map(x=><option key={x}>{x}</option>)}</select><input className="inp" placeholder="Customer" value={f.customerRef} onChange={e=>setF({...f,customerRef:e.target.value})}/><select className="inp" value={f.contractId} onChange={e=>{const c=(contracts.data??[]).find(x=>x.id===e.target.value);setF({...f,contractId:e.target.value,customerRef:c?.customerRef??f.customerRef})}}><option value="">No maintenance contract</option>{(contracts.data??[]).filter(c=>c.active).map(c=><option value={c.id} key={c.id}>{c.contractRef} · {c.customerRef}</option>)}</select><input className="inp" placeholder="Customer approval ref" value={f.customerApprovalRef} onChange={e=>setF({...f,customerApprovalRef:e.target.value})}/><input className="inp" type="datetime-local" value={f.plannedStart} onChange={e=>setF({...f,plannedStart:e.target.value})}/><input className="inp" type="datetime-local" value={f.plannedEnd} onChange={e=>setF({...f,plannedEnd:e.target.value})}/><input className="inp" type="number" step="0.5" value={f.plannedHours} onChange={e=>setF({...f,plannedHours:e.target.value})}/></div><button className="btn pri" disabled={!f.title||(!f.tail&&!f.componentRef)} onClick={()=>create.mutate()}>Create</button></Card>
    <Card title="Work-order board"><table className="t"><thead><tr><th>Order</th><th>Subject</th><th>Type</th><th>Status</th><th>Hours / SLA</th><th>Control</th></tr></thead><tbody>{(q.data??[]).map(w=><tr key={w.id}><td className="mono"><button className="btn sm" onClick={()=>setSelected(selected===w.id?null:w.id)}>{w.id}</button><div className="sub">{w.title}</div></td><td>{w.tail??w.componentRef}<div className="sub">{w.station} · {w.aircraftType}</div></td><td>{w.orderType}<br/><Pill tone={w.priority==='AOG'?'red':w.priority==='HIGH'?'amber':'cyan'}>{w.priority}</Pill></td><td><Pill tone={tone(w.status)}>{w.status}</Pill>{w.holdReason&&<div className="sub">{w.holdReason}</div>}</td><td>{w.plannedHours.toFixed(1)} / {(w.actualMinutes/60).toFixed(1)} h<div className="sub">SLA {zulu(w.slaDueAt)}</div></td><td>{next(w.status).map(n=><span key={n} className="row">{n==='HOLD'&&<input className="inp" placeholder="Reason" value={reasons[w.id]??''} onChange={e=>setReasons(x=>({...x,[w.id]:e.target.value}))}/>}<button className="btn sm" onClick={()=>st.mutate({id:w.id,state:n})}>{n}</button></span>)}</td></tr>)}</tbody></table></Card>
    {selected&&<WorkOrderDetail id={selected} order={(q.data??[]).find(x=>x.id===selected)!}/>}<ErrorNote error={q.error??create.error??st.error??contracts.error}/>
  </div>
}

function WorkOrderDetail({id,order}:{id:string;order:WO}){
  const qc=useQueryClient();
  const ass=useQuery({queryKey:['mnt','assignments',id],queryFn:()=>api<Assignment[]>(`/amo/maintenance/work-orders/${id}/assignments`)});
  const people=useQuery({queryKey:['mnt','personnel',order.station,order.aircraftType],queryFn:()=>api<Person[]>(`/amo/maintenance/personnel?station=${order.station}${order.aircraftType?`&aircraftType=${order.aircraftType}`:''}`)});
  const outs=useQuery({queryKey:['mnt','outs',id],queryFn:()=>api<Outsource[]>(`/amo/maintenance/outsourced-work?workOrderId=${id}`)});
  const prog=useQuery({queryKey:['mnt','progress',id],queryFn:()=>api<Progress[]>(`/amo/maintenance/progress-reports?workOrderId=${id}`)});
  const kits=useQuery({queryKey:['mnt','kits',id],queryFn:()=>api<MaterialKit[]>(`/amo/maintenance/material-kits?workOrderId=${id}`)});
  const [af,setAf]=useState({personnelId:'',assignmentRole:'MECHANIC',trade:'',shiftRef:'',plannedMinutes:'0'});const [times,setTimes]=useState<Record<string,string>>({});const [outRefs,setOutRefs]=useState<Record<string,string>>({});
  const [of,setOf]=useState({vendorRef:'',scope:'',purchaseOrderRef:'',outboundRef:'',dueAt:''});const [pf,setPf]=useState({customerRef:order.customerRef??'',percentComplete:'0',forecastRelease:'',tatVarianceMinutes:'0',summary:'',risks:''});
  const [kf,setKf]=useState({kitNo:'',partNo:'',qtyRequired:'1',stockRef:'',certificateRef:''});const [picks,setPicks]=useState<Record<string,string>>({});
  const assign=useMutation({mutationFn:()=>post(`/amo/maintenance/work-orders/${id}/assignments`,{...af,trade:af.trade||null,shiftRef:af.shiftRef||null,plannedMinutes:Number(af.plannedMinutes)}),onSuccess:()=>refresh(qc)});
  const book=useMutation({mutationFn:(aid:string)=>post(`/amo/maintenance/work-orders/${id}/assignments/${aid}/time`,{actualMinutes:Number(times[aid]??0)}),onSuccess:()=>refresh(qc)});
  const release=useMutation({mutationFn:(aid:string)=>post(`/amo/maintenance/work-orders/${id}/assignments/${aid}/release`),onSuccess:()=>refresh(qc)});
  const addOut=useMutation({mutationFn:()=>post('/amo/maintenance/outsourced-work',{workOrderId:id,wpId:null,vendorRef:of.vendorRef,scope:of.scope,purchaseOrderRef:of.purchaseOrderRef||null,outboundRef:of.outboundRef||null,dueAt:of.dueAt?new Date(of.dueAt).toISOString():null}),onSuccess:()=>refresh(qc)});
  const outState=useMutation({mutationFn:(x:{id:string;state:string;ref?:string})=>post(`/amo/maintenance/outsourced-work/${x.id}/state`,{state:x.state,returnReleaseRef:x.ref??null}),onSuccess:()=>refresh(qc)});
  const addProgress=useMutation({mutationFn:()=>post('/amo/maintenance/progress-reports',{workOrderId:id,wpId:null,customerRef:pf.customerRef,percentComplete:Number(pf.percentComplete),forecastRelease:pf.forecastRelease?new Date(pf.forecastRelease).toISOString():null,tatVarianceMinutes:Number(pf.tatVarianceMinutes),summary:pf.summary,risks:pf.risks.split(',').map(x=>x.trim()).filter(Boolean)}),onSuccess:()=>refresh(qc)});
  const createKit=useMutation({mutationFn:()=>post('/amo/maintenance/material-kits',{workOrderId:id,wpId:null,kitNo:kf.kitNo,station:order.station}),onSuccess:()=>refresh(qc)});
  const addKitItem=useMutation({mutationFn:(kitId:string)=>post(`/amo/maintenance/material-kits/${kitId}/items`,{partNo:kf.partNo,description:null,qtyRequired:Number(kf.qtyRequired),stockRef:kf.stockRef||null,certificateRef:kf.certificateRef||null}),onSuccess:()=>refresh(qc)});
  const pickKitItem=useMutation({mutationFn:(x:{kitId:string;item:MaterialKitItem})=>post(`/amo/maintenance/material-kits/${x.kitId}/items/${x.item.id}/pick`,{qtyPicked:Number(picks[x.item.id]??x.item.qtyRequired),stockRef:x.item.stockRef,certificateRef:x.item.certificateRef}),onSuccess:()=>refresh(qc)});
  const kitState=useMutation({mutationFn:(x:{id:string;state:string})=>post(`/amo/maintenance/material-kits/${x.id}/state`,{state:x.state}),onSuccess:()=>refresh(qc)});
  return <Card title={`${id} · Production detail`} meta="Workforce, outsource and customer/TAT controls remain on the work order"><div className="two-col"><div><h4>Workforce</h4><div className="row"><select className="inp" value={af.personnelId} onChange={e=>setAf({...af,personnelId:e.target.value})}><option value="">Select person</option>{(people.data??[]).map(p=><option key={p.id} value={p.id}>{p.name}{p.authorised?' · auth':''}</option>)}</select><select className="inp" value={af.assignmentRole} onChange={e=>setAf({...af,assignmentRole:e.target.value})}>{['MECHANIC','SUPERVISOR','INSPECTOR','SPECIALIST'].map(x=><option key={x}>{x}</option>)}</select><input className="inp" placeholder="Trade" value={af.trade} onChange={e=>setAf({...af,trade:e.target.value})}/><input className="inp" type="number" placeholder="Planned min" value={af.plannedMinutes} onChange={e=>setAf({...af,plannedMinutes:e.target.value})}/><button className="btn sm" disabled={!af.personnelId} onClick={()=>assign.mutate()}>Assign</button></div>{(ass.data??[]).map(a=><div className="block" key={a.id}>{a.personnelId} · {a.assignmentRole} · {a.trade??'—'} · planned {a.plannedMinutes}m / actual {a.actualMinutes}m {!a.releasedAt&&<span className="row"><input className="inp" style={{width:100}} type="number" value={times[a.id]??String(a.actualMinutes)} onChange={e=>setTimes(x=>({...x,[a.id]:e.target.value}))}/><button className="btn sm" onClick={()=>book.mutate(a.id)}>Book</button><button className="btn sm" onClick={()=>release.mutate(a.id)}>Release</button></span>}</div>)}</div><div><h4>Outsourced work</h4><div className="form-grid"><input className="inp" placeholder="Vendor" value={of.vendorRef} onChange={e=>setOf({...of,vendorRef:e.target.value})}/><input className="inp" placeholder="PO" value={of.purchaseOrderRef} onChange={e=>setOf({...of,purchaseOrderRef:e.target.value})}/><input className="inp" type="datetime-local" value={of.dueAt} onChange={e=>setOf({...of,dueAt:e.target.value})}/><input className="inp" placeholder="Scope" value={of.scope} onChange={e=>setOf({...of,scope:e.target.value})}/></div><button className="btn sm" disabled={!of.vendorRef||of.scope.length<5} onClick={()=>addOut.mutate()}>Add outsource</button>{(outs.data??[]).map(o=><div className="block" key={o.id}><Pill tone={tone(o.status)}>{o.status}</Pill> {o.vendor_ref} · {o.scope}<div className="row">{o.status==='PLANNED'&&<button className="btn sm" onClick={()=>outState.mutate({id:o.id,state:'SENT'})}>Sent</button>}{['SENT','IN_WORK'].includes(o.status)&&<><input className="inp" placeholder="Return release/trace ref" value={outRefs[o.id]??''} onChange={e=>setOutRefs(x=>({...x,[o.id]:e.target.value}))}/><button className="btn sm" disabled={!(outRefs[o.id]??'').trim()} onClick={()=>outState.mutate({id:o.id,state:'RETURNED',ref:(outRefs[o.id]??'').trim()})}>Returned</button></>}{o.status==='RETURNED'&&<button className="btn sm" onClick={()=>outState.mutate({id:o.id,state:'ACCEPTED',ref:o.return_release_ref??undefined})}>Accept</button>}</div></div>)}</div></div><h4>Material kitting</h4><div className="row"><input className="inp" placeholder="Kit no" value={kf.kitNo} onChange={e=>setKf({...kf,kitNo:e.target.value})}/><button className="btn sm" disabled={!kf.kitNo} onClick={()=>createKit.mutate()}>Create kit</button><input className="inp" placeholder="Part no" value={kf.partNo} onChange={e=>setKf({...kf,partNo:e.target.value})}/><input className="inp" placeholder="Stock ref" value={kf.stockRef} onChange={e=>setKf({...kf,stockRef:e.target.value})}/><input className="inp" placeholder="Certificate ref" value={kf.certificateRef} onChange={e=>setKf({...kf,certificateRef:e.target.value})}/><input className="inp" type="number" min="0.01" step="0.01" value={kf.qtyRequired} onChange={e=>setKf({...kf,qtyRequired:e.target.value})}/></div>{(kits.data??[]).map(k=><div className="block" key={k.id}><div className="row"><b>{k.kitNo}</b><Pill tone={tone(k.status)}>{k.status}</Pill>{k.status==='PLANNED'&&<button className="btn sm" onClick={()=>kitState.mutate({id:k.id,state:'PICKING'})}>Start picking</button>}{k.status==='PICKING'&&<button className="btn sm" onClick={()=>kitState.mutate({id:k.id,state:'READY'})}>Ready</button>}{k.status==='READY'&&<button className="btn sm" onClick={()=>kitState.mutate({id:k.id,state:'ISSUED'})}>Issue</button>}{k.status==='ISSUED'&&<button className="btn sm" onClick={()=>kitState.mutate({id:k.id,state:'CLOSED'})}>Close</button>}{['PLANNED','PICKING','READY'].includes(k.status)&&kf.partNo&&<button className="btn sm" onClick={()=>addKitItem.mutate(k.id)}>Add {kf.partNo}</button>}</div>{k.items.map(i=><div className="row" key={i.id}>{i.partNo} · {i.qtyPicked}/{i.qtyRequired}<input className="inp" style={{width:90}} type="number" min="0" max={i.qtyRequired} value={picks[i.id]??String(i.qtyPicked)} onChange={e=>setPicks(x=>({...x,[i.id]:e.target.value}))}/><button className="btn sm" disabled={!['PLANNED','PICKING'].includes(k.status)} onClick={()=>pickKitItem.mutate({kitId:k.id,item:i})}>Pick</button><span className="sub">{i.stockRef??'stock ref pending'} · {i.certificateRef??'cert pending'}</span></div>)}</div>)}<h4>Customer / TAT progress</h4><div className="row"><input className="inp" placeholder="Customer" value={pf.customerRef} onChange={e=>setPf({...pf,customerRef:e.target.value})}/><input className="inp" type="number" min="0" max="100" value={pf.percentComplete} onChange={e=>setPf({...pf,percentComplete:e.target.value})}/><input className="inp" type="datetime-local" value={pf.forecastRelease} onChange={e=>setPf({...pf,forecastRelease:e.target.value})}/><input className="inp" placeholder="Summary" value={pf.summary} onChange={e=>setPf({...pf,summary:e.target.value})}/><button className="btn sm" disabled={!pf.customerRef||pf.summary.length<5} onClick={()=>addProgress.mutate()}>Record progress</button></div>{(prog.data??[]).slice(0,5).map(r=><div className="block" key={r.id}>{r.percent_complete}% · forecast {zulu(r.forecast_release)} · {r.summary}</div>)}<ErrorNote error={ass.error??people.error??outs.error??prog.error??kits.error??assign.error??book.error??release.error??addOut.error??outState.error??addProgress.error??createKit.error??addKitItem.error??pickKitItem.error??kitState.error}/></Card>
}

function Line({station}:{station:string}){
  const qc=useQueryClient();const q=useQuery({queryKey:['mnt','line',station],queryFn:()=>api<LV[]>(`/amo/maintenance/line-visits${station?`?station=${station}`:''}`)});
  const [f,setF]=useState({tail:'',aircraftType:'A320',station:station||'ENGM',inboundFlight:'',outboundFlight:'',scheduledIn:'',scheduledOut:'',workOrderId:'',openDefects:'0',deferredDefectRefs:''});
  const [ctl,setCtl]=useState<Record<string,{openDefects:string;deferred:string;note:string}>>({});
  const create=useMutation({mutationFn:()=>post('/amo/maintenance/line-visits',{...f,inboundFlight:f.inboundFlight||null,outboundFlight:f.outboundFlight||null,workOrderId:f.workOrderId||null,openDefects:Number(f.openDefects),deferredDefectRefs:f.deferredDefectRefs.split(',').map(x=>x.trim()).filter(Boolean),turnaroundNotes:null,scheduledIn:new Date(f.scheduledIn).toISOString(),scheduledOut:new Date(f.scheduledOut).toISOString()}),onSuccess:()=>refresh(qc)});
  const st=useMutation({mutationFn:(x:{id:string;state:string;v:LV})=>{const c=ctl[x.id]??{openDefects:String(x.v.openDefects),deferred:x.v.deferredDefectRefs.join(','),note:''};return post(`/amo/maintenance/line-visits/${x.id}/state`,{state:x.state,note:c.note||null,openDefects:Number(c.openDefects),deferredDefectRefs:c.deferred.split(',').map(y=>y.trim()).filter(Boolean)})},onSuccess:()=>refresh(qc)});
  const next=(s:string)=>({PLANNED:['ARRIVED','CANCELLED'],ARRIVED:['IN_MAINTENANCE','RELEASED'],IN_MAINTENANCE:['RELEASED'],RELEASED:['DEPARTED']} as Record<string,string[]>)[s]??[];
  return <div className="stack"><Card title="Plan line visit"><div className="form-grid"><input className="inp mono" placeholder="Tail" value={f.tail} onChange={e=>setF({...f,tail:e.target.value.toUpperCase()})}/><input className="inp" value={f.aircraftType} onChange={e=>setF({...f,aircraftType:e.target.value.toUpperCase()})}/><input className="inp mono" value={f.station} maxLength={4} onChange={e=>setF({...f,station:e.target.value.toUpperCase()})}/><input className="inp" placeholder="Inbound" value={f.inboundFlight} onChange={e=>setF({...f,inboundFlight:e.target.value})}/><input className="inp" placeholder="Outbound" value={f.outboundFlight} onChange={e=>setF({...f,outboundFlight:e.target.value})}/><input className="inp" type="datetime-local" value={f.scheduledIn} onChange={e=>setF({...f,scheduledIn:e.target.value})}/><input className="inp" type="datetime-local" value={f.scheduledOut} onChange={e=>setF({...f,scheduledOut:e.target.value})}/><input className="inp" placeholder="Work order" value={f.workOrderId} onChange={e=>setF({...f,workOrderId:e.target.value})}/><input className="inp" type="number" min="0" value={f.openDefects} onChange={e=>setF({...f,openDefects:e.target.value})}/><input className="inp" placeholder="Deferred defect refs (comma)" value={f.deferredDefectRefs} onChange={e=>setF({...f,deferredDefectRefs:e.target.value})}/></div><button className="btn pri" disabled={!f.tail||!f.scheduledIn||!f.scheduledOut} onClick={()=>create.mutate()}>Plan</button></Card><Card title="Line maintenance control"><table className="t"><thead><tr><th>Aircraft</th><th>Flights / window</th><th>Defect control</th><th>Status / control</th></tr></thead><tbody>{(q.data??[]).map(v=>{const c=ctl[v.id]??{openDefects:String(v.openDefects),deferred:v.deferredDefectRefs.join(','),note:v.turnaroundNotes??''};return <tr key={v.id}><td className="mono">{v.tail}<div className="sub">{v.aircraftType} · {v.station}</div></td><td>{v.inboundFlight??'—'} → {v.outboundFlight??'—'}<div className="sub">{zulu(v.scheduledIn)} → {zulu(v.scheduledOut)}</div></td><td><input className="inp" type="number" min="0" value={c.openDefects} onChange={e=>setCtl(x=>({...x,[v.id]:{...c,openDefects:e.target.value}}))}/><input className="inp" placeholder="Deferred refs" value={c.deferred} onChange={e=>setCtl(x=>({...x,[v.id]:{...c,deferred:e.target.value}}))}/><input className="inp" placeholder="Turnaround / shift note" value={c.note} onChange={e=>setCtl(x=>({...x,[v.id]:{...c,note:e.target.value}}))}/></td><td><Pill tone={tone(v.status)}>{v.status}</Pill><div className="row">{next(v.status).map(n=><button className="btn sm" key={n} onClick={()=>st.mutate({id:v.id,state:n,v})}>{n}</button>)}</div></td></tr>})}</tbody></table></Card><ErrorNote error={q.error??create.error??st.error}/></div>
}

function Handovers({station}:{station:string}){const qc=useQueryClient();const q=useQuery({queryKey:['mnt','handover',station],queryFn:()=>api<H[]>(`/amo/maintenance/handovers${station?`?station=${station}`:''}`)});const [f,setF]=useState({station:station||'ENGM',workArea:'LINE',outgoingShift:'Day',incomingShift:'Night',summary:'',itemType:'AIRCRAFT',reference:'',description:'',priority:'NORMAL'});const [res,setRes]=useState<Record<string,string>>({});const create=useMutation({mutationFn:()=>post('/amo/maintenance/handovers',{station:f.station,workArea:f.workArea,outgoingShift:f.outgoingShift,incomingShift:f.incomingShift,summary:f.summary,items:[{itemType:f.itemType,reference:f.reference,description:f.description,priority:f.priority}]}),onSuccess:()=>refresh(qc)});const accept=useMutation({mutationFn:(id:string)=>post(`/amo/maintenance/handovers/${id}/accept`),onSuccess:()=>refresh(qc)});const resolve=useMutation({mutationFn:(x:{h:string;i:string})=>post(`/amo/maintenance/handovers/${x.h}/items/${x.i}/resolve`,{resolution:res[x.i]}),onSuccess:()=>refresh(qc)});return <div className="stack"><Card title="Controlled shift handover"><div className="form-grid"><input className="inp mono" value={f.station} maxLength={4} onChange={e=>setF({...f,station:e.target.value.toUpperCase()})}/><select className="inp" value={f.workArea} onChange={e=>setF({...f,workArea:e.target.value})}>{['LINE','BASE','SHOP','AOG','TOOL_CRIB'].map(x=><option key={x}>{x}</option>)}</select><input className="inp" value={f.outgoingShift} onChange={e=>setF({...f,outgoingShift:e.target.value})}/><input className="inp" value={f.incomingShift} onChange={e=>setF({...f,incomingShift:e.target.value})}/><input className="inp" placeholder="Summary" value={f.summary} onChange={e=>setF({...f,summary:e.target.value})}/><select className="inp" value={f.itemType} onChange={e=>setF({...f,itemType:e.target.value})}>{['AIRCRAFT','WORK_ORDER','TASK_CARD','OPEN_PANEL','ISOLATION','TOOL','MATERIAL','NCR','GROUND_RUN','SAFETY','OTHER'].map(x=><option key={x}>{x}</option>)}</select><input className="inp" placeholder="Reference" value={f.reference} onChange={e=>setF({...f,reference:e.target.value})}/><input className="inp" placeholder="Description" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></div><button className="btn pri" disabled={f.summary.length<10||!f.reference||f.description.length<3} onClick={()=>create.mutate()}>Open handover</button></Card>{(q.data??[]).map(h=><Card key={h.id} title={`${h.station} · ${h.workArea} · ${h.outgoingShift} → ${h.incomingShift}`} meta={zulu(h.handedOverAt)}><div className="row"><Pill tone={tone(h.status)}>{h.status}</Pill>{h.summary}{h.status==='OPEN'&&<button className="btn sm" onClick={()=>accept.mutate(h.id)}>Accept</button>}</div>{h.items.map(i=><div className="block" key={i.id}><div className="row"><Pill>{i.itemType}</Pill><b>{i.reference}</b>{i.description}<Pill tone={tone(i.status)}>{i.status}</Pill></div>{i.status==='OPEN'&&<div className="row"><input className="inp" placeholder="Resolution" value={res[i.id]??''} onChange={e=>setRes(x=>({...x,[i.id]:e.target.value}))}/><button className="btn sm" disabled={(res[i.id]??'').length<5} onClick={()=>resolve.mutate({h:h.id,i:i.id})}>Resolve</button></div>}</div>)}</Card>)}<ErrorNote error={q.error??create.error??accept.error??resolve.error}/></div>}

function Tools({station}:{station:string}){
  const qc=useQueryClient();const q=useQuery({queryKey:['mnt','tools',station],queryFn:()=>api<Tool[]>(`/amo/maintenance/tools${station?`?station=${station}`:''}`)});const reservations=useQuery({queryKey:['mnt','tool-res'],queryFn:()=>api<Reservation[]>('/amo/maintenance/tool-reservations')});
  const [f,setF]=useState({toolNo:'',serial:'',description:'',station:station||'ENGM',crib:'MAIN',kitCode:'',calibrationRequired:true,calibratedUntil:'',certificateRef:''});const [mv,setMv]=useState<Record<string,{movement:string;reference:string;workOrderId:string;taskCardId:string;calibratedUntil:string;certificateRef:string}>>({});const [rv,setRv]=useState<Record<string,{workOrderId:string;taskCardId:string;from:string;until:string}>>({});
  const create=useMutation({mutationFn:()=>post('/amo/maintenance/tools',{...f,serial:f.serial||null,kitCode:f.kitCode||null,calibratedUntil:f.calibratedUntil||null,certificateRef:f.certificateRef||null}),onSuccess:()=>refresh(qc)});const move=useMutation({mutationFn:(id:string)=>{const x=mv[id]??{movement:'ISSUE',reference:'',workOrderId:'',taskCardId:'',calibratedUntil:'',certificateRef:''};return post(`/amo/maintenance/tools/${id}/movements`,{...x,workOrderId:x.workOrderId||null,taskCardId:x.taskCardId||null,personnelId:null,note:null,calibratedUntil:x.calibratedUntil||null,certificateRef:x.certificateRef||null})},onSuccess:()=>refresh(qc)});
  const reserve=useMutation({mutationFn:(id:string)=>{const x=rv[id];return post(`/amo/maintenance/tools/${id}/reservations`,{workOrderId:x.workOrderId||null,taskCardId:x.taskCardId||null,reservedFrom:new Date(x.from).toISOString(),reservedUntil:new Date(x.until).toISOString()})},onSuccess:()=>refresh(qc)});const cancel=useMutation({mutationFn:(id:string)=>post(`/amo/maintenance/tool-reservations/${id}/cancel`),onSuccess:()=>refresh(qc)});
  return <div className="stack"><Card title="Register tool"><div className="form-grid"><input className="inp" placeholder="Tool no" value={f.toolNo} onChange={e=>setF({...f,toolNo:e.target.value})}/><input className="inp" placeholder="Serial" value={f.serial} onChange={e=>setF({...f,serial:e.target.value})}/><input className="inp" placeholder="Description" value={f.description} onChange={e=>setF({...f,description:e.target.value})}/><input className="inp mono" value={f.station} onChange={e=>setF({...f,station:e.target.value.toUpperCase()})}/><input className="inp" placeholder="Crib" value={f.crib} onChange={e=>setF({...f,crib:e.target.value})}/><input className="inp" placeholder="Kit code" value={f.kitCode} onChange={e=>setF({...f,kitCode:e.target.value})}/><label className="row"><input type="checkbox" checked={f.calibrationRequired} onChange={e=>setF({...f,calibrationRequired:e.target.checked})}/> Calibration controlled</label><input className="inp" type="date" value={f.calibratedUntil} onChange={e=>setF({...f,calibratedUntil:e.target.value})}/><input className="inp" placeholder="Certificate" value={f.certificateRef} onChange={e=>setF({...f,certificateRef:e.target.value})}/></div><button className="btn pri" onClick={()=>create.mutate()}>Register</button></Card><Card title="Tool crib & reservations"><table className="t"><thead><tr><th>Tool</th><th>Location / calibration</th><th>Status</th><th>Reservation / movement</th></tr></thead><tbody>{(q.data??[]).map(t=>{const x=mv[t.id]??{movement:'ISSUE',reference:'',workOrderId:'',taskCardId:'',calibratedUntil:'',certificateRef:''};const r=rv[t.id]??{workOrderId:'',taskCardId:'',from:'',until:''};const active=(reservations.data??[]).filter(z=>z.toolId===t.id);return <tr key={t.id}><td>{t.toolNo}<div className="sub">{t.serial} · {t.description} · kit {t.kitCode??'—'}</div></td><td>{t.station}/{t.crib}<div className="sub">cal {t.calibratedUntil??'n/a'} · {t.certificateRef}</div></td><td><Pill tone={tone(t.status)}>{t.status}</Pill>{active.map(a=><div className="sub" key={a.id}>{a.status} {a.workOrderId??a.taskCardId} {zulu(a.reservedFrom)} <button className="btn sm" onClick={()=>cancel.mutate(a.id)}>Cancel</button></div>)}</td><td><div className="row"><input className="inp" placeholder="Reserve WO" value={r.workOrderId} onChange={e=>setRv(m=>({...m,[t.id]:{...r,workOrderId:e.target.value}}))}/><input className="inp" placeholder="or Task Card" value={r.taskCardId} onChange={e=>setRv(m=>({...m,[t.id]:{...r,taskCardId:e.target.value}}))}/><input className="inp" type="datetime-local" value={r.from} onChange={e=>setRv(m=>({...m,[t.id]:{...r,from:e.target.value}}))}/><input className="inp" type="datetime-local" value={r.until} onChange={e=>setRv(m=>({...m,[t.id]:{...r,until:e.target.value}}))}/><button className="btn sm" disabled={!r.from||!r.until||(!r.workOrderId&&!r.taskCardId)} onClick={()=>reserve.mutate(t.id)}>Reserve</button></div><select className="inp" value={x.movement} onChange={e=>setMv(m=>({...m,[t.id]:{...x,movement:e.target.value}}))}>{['ISSUE','RETURN','SEND_CALIBRATION','RETURN_CALIBRATION','QUARANTINE','MARK_LOST','MARK_DAMAGED','RETIRE'].map(v=><option key={v}>{v}</option>)}</select><input className="inp" placeholder="Reference" value={x.reference} onChange={e=>setMv(m=>({...m,[t.id]:{...x,reference:e.target.value}}))}/>{x.movement==='ISSUE'&&<input className="inp" placeholder="WO" value={x.workOrderId} onChange={e=>setMv(m=>({...m,[t.id]:{...x,workOrderId:e.target.value}}))}/>} {x.movement==='RETURN_CALIBRATION'&&<div className="row"><input className="inp" type="date" value={x.calibratedUntil} onChange={e=>setMv(m=>({...m,[t.id]:{...x,calibratedUntil:e.target.value}}))}/><input className="inp" placeholder="Certificate" value={x.certificateRef} onChange={e=>setMv(m=>({...m,[t.id]:{...x,certificateRef:e.target.value}}))}/></div>}<button className="btn sm" disabled={!x.reference} onClick={()=>move.mutate(t.id)}>Record</button></td></tr>})}</tbody></table></Card><ErrorNote error={q.error??reservations.error??create.error??move.error??reserve.error??cancel.error}/></div>
}

function Shops(){
  const qc=useQueryClient();const q=useQuery({queryKey:['mnt','shops'],queryFn:()=>api<Shop[]>('/amo/maintenance/shop-orders')});const [selected,setSelected]=useState<string|null>(null);
  const [f,setF]=useState({shopType:'COMPONENT',partNo:'',serial:'',customerRef:'',incomingCondition:'',workscope:'',inductionRef:'',plannedRelease:''});const [finding,setFinding]=useState<Record<string,string>>({});const [test,setTest]=useState<Record<string,string>>({});const [cert,setCert]=useState<Record<string,string>>({});
  const create=useMutation({mutationFn:()=>post('/amo/maintenance/shop-orders',{...f,customerRef:f.customerRef||null,plannedRelease:f.plannedRelease||null}),onSuccess:()=>refresh(qc)});const st=useMutation({mutationFn:(x:{id:string,state:string})=>post(`/amo/maintenance/shop-orders/${x.id}/state`,{state:x.state,testResult:test[x.id]||null,releaseCertificateRef:cert[x.id]||null,reason:null}),onSuccess:()=>refresh(qc)});const add=useMutation({mutationFn:(id:string)=>post(`/amo/maintenance/shop-orders/${id}/findings`,{finding:finding[id],disposition:null,partNo:null,serial:null,repairRef:null}),onSuccess:()=>refresh(qc)});const close=useMutation({mutationFn:(x:{id:string;fid:string})=>post(`/amo/maintenance/shop-orders/${x.id}/findings/${x.fid}/state`,{state:'CLOSED',disposition:null,repairRef:null}),onSuccess:()=>refresh(qc)});const next=(s:string)=>({INDUCTED:['TEARDOWN'],TEARDOWN:['INSPECTION'],INSPECTION:['REPAIR','ASSEMBLY'],REPAIR:['ASSEMBLY'],ASSEMBLY:['TEST'],TEST:['READY_FOR_RELEASE'],READY_FOR_RELEASE:['RELEASED']} as Record<string,string[]>)[s]??[];
  return <div className="stack"><Card title="Induct shop order"><div className="form-grid"><select className="inp" value={f.shopType} onChange={e=>setF({...f,shopType:e.target.value})}>{['ENGINE','APU','COMPONENT','WHEEL_BRAKE','BATTERY','AVIONICS','STRUCTURES','OTHER'].map(x=><option key={x}>{x}</option>)}</select><input className="inp" placeholder="Part no" value={f.partNo} onChange={e=>setF({...f,partNo:e.target.value})}/><input className="inp" placeholder="Serial" value={f.serial} onChange={e=>setF({...f,serial:e.target.value})}/><input className="inp" placeholder="Incoming condition" value={f.incomingCondition} onChange={e=>setF({...f,incomingCondition:e.target.value})}/><input className="inp" placeholder="Induction ref" value={f.inductionRef} onChange={e=>setF({...f,inductionRef:e.target.value})}/><input className="inp" type="date" value={f.plannedRelease} onChange={e=>setF({...f,plannedRelease:e.target.value})}/><textarea className="inp" placeholder="Workscope" value={f.workscope} onChange={e=>setF({...f,workscope:e.target.value})}/></div><button className="btn pri" disabled={!f.partNo||!f.serial||f.workscope.length<10||!f.inductionRef} onClick={()=>create.mutate()}>Induct</button></Card>{(q.data??[]).map(o=><Card key={o.id} title={`${o.id} · ${o.partNo}/${o.serial}`} meta={o.shopType}><div className="row"><button className="btn sm" onClick={()=>setSelected(selected===o.id?null:o.id)}>Piece-parts</button><Pill tone={tone(o.status)}>{o.status}</Pill>{o.workscope}</div><div className="row">{next(o.status).map(n=><span key={n} className="row">{n==='READY_FOR_RELEASE'&&<input className="inp" placeholder="Test-cell/bench result ref" value={test[o.id]??''} onChange={e=>setTest(x=>({...x,[o.id]:e.target.value}))}/>} {n==='RELEASED'&&<input className="inp" placeholder="Release certificate" value={cert[o.id]??''} onChange={e=>setCert(x=>({...x,[o.id]:e.target.value}))}/>}<button className="btn sm" onClick={()=>st.mutate({id:o.id,state:n})}>{n}</button></span>)}</div>{o.findings.map(x=><div className="block" key={x.id}><Pill tone={tone(x.status)}>{x.status}</Pill> {x.finding} {x.status!=='CLOSED'&&<button className="btn sm" onClick={()=>close.mutate({id:o.id,fid:x.id})}>Close</button>}</div>)}<div className="row"><input className="inp" placeholder="Finding" value={finding[o.id]??''} onChange={e=>setFinding(x=>({...x,[o.id]:e.target.value}))}/><button className="btn sm" onClick={()=>add.mutate(o.id)}>Add finding</button></div>{selected===o.id&&<ShopPieceParts shopOrderId={o.id}/>}</Card>)}<ErrorNote error={q.error??create.error??st.error??add.error??close.error}/></div>
}

function ShopPieceParts({shopOrderId}:{shopOrderId:string}){
 const qc=useQueryClient();const q=useQuery({queryKey:['mnt','piece-parts',shopOrderId],queryFn:()=>api<PiecePart[]>(`/amo/maintenance/shop-orders/${shopOrderId}/piece-parts`)});const [f,setF]=useState({partNo:'',serial:'',lotNo:'',description:'',incomingCondition:'',disposition:'HOLD',repairSchemeRef:'',externalOrderRef:'',traceRef:''});
 const add=useMutation({mutationFn:()=>post(`/amo/maintenance/shop-orders/${shopOrderId}/piece-parts`,{...f,serial:f.serial||null,lotNo:f.lotNo||null,description:f.description||null,repairSchemeRef:f.repairSchemeRef||null,externalOrderRef:f.externalOrderRef||null,traceRef:f.traceRef||null}),onSuccess:()=>refresh(qc)});const state=useMutation({mutationFn:(x:{id:string;disposition:string;installed:boolean})=>post(`/amo/maintenance/shop-orders/${shopOrderId}/piece-parts/${x.id}/state`,{disposition:x.disposition,installed:x.installed}),onSuccess:()=>refresh(qc)});
 return <div className="block"><h4>Piece-parts / teardown trace</h4><div className="row"><input className="inp" placeholder="Part no" value={f.partNo} onChange={e=>setF({...f,partNo:e.target.value})}/><input className="inp" placeholder="Serial/lot" value={f.serial} onChange={e=>setF({...f,serial:e.target.value})}/><input className="inp" placeholder="Condition" value={f.incomingCondition} onChange={e=>setF({...f,incomingCondition:e.target.value})}/><input className="inp" placeholder="Trace ref" value={f.traceRef} onChange={e=>setF({...f,traceRef:e.target.value})}/><input className="inp" placeholder="Repair scheme ref" value={f.repairSchemeRef} onChange={e=>setF({...f,repairSchemeRef:e.target.value})}/><input className="inp" placeholder="External repair order" value={f.externalOrderRef} onChange={e=>setF({...f,externalOrderRef:e.target.value})}/><button className="btn sm" disabled={!f.partNo||!f.incomingCondition} onClick={()=>add.mutate()}>Add</button></div>{(q.data??[]).map(pp=><div className="row" key={pp.id}><span>{pp.partNo}/{pp.serial??pp.lotNo??'—'}</span><Pill tone={tone(pp.disposition)}>{pp.disposition}</Pill><select className="inp" defaultValue={pp.disposition} onChange={e=>state.mutate({id:pp.id,disposition:e.target.value,installed:false})}>{['HOLD','SERVICEABLE','REPAIR','SCRAP','REPLACE','EXTERNAL_REPAIR'].map(x=><option key={x}>{x}</option>)}</select>{['SERVICEABLE','REPLACE'].includes(pp.disposition)&&!pp.installed&&<button className="btn sm" onClick={()=>state.mutate({id:pp.id,disposition:pp.disposition,installed:true})}>Install</button>}{pp.installed&&<Pill tone="green">INSTALLED</Pill>}</div>)}<ErrorNote error={q.error??add.error??state.error}/></div>
}

function AogCases(){
 const qc=useQueryClient();const q=useQuery({queryKey:['mnt','aog'],queryFn:()=>api<Aog[]>('/amo/maintenance/aog')});const [f,setF]=useState({tail:'',station:'ENGM',defectRef:'',workOrderId:'',severity:'AOG',technicalSummary:'',recoveryEta:'',requiredPart:'',logisticsRef:'',operationalImpact:'',estimatedCostMinor:'0',currency:'USD'});const [u,setU]=useState<Record<string,{updateType:string;note:string;status:string;estimatedCostMinor:string}>>({});
 const create=useMutation({mutationFn:()=>post('/amo/maintenance/aog',{...f,workOrderId:f.workOrderId||null,recoveryEta:f.recoveryEta?new Date(f.recoveryEta).toISOString():null,requiredPart:f.requiredPart||null,logisticsRef:f.logisticsRef||null,operationalImpact:f.operationalImpact||null,estimatedCostMinor:Number(f.estimatedCostMinor)}),onSuccess:()=>refresh(qc)});const update=useMutation({mutationFn:(id:string)=>{const x=u[id]??{updateType:'TECHNICAL',note:'',status:'',estimatedCostMinor:''};return post(`/amo/maintenance/aog/${id}/updates`,{updateType:x.updateType,note:x.note,status:x.status||undefined,recoveryEta:null,estimatedCostMinor:x.estimatedCostMinor?Number(x.estimatedCostMinor):undefined})},onSuccess:()=>refresh(qc)});
 return <div className="stack"><Card title="Open AOG"><div className="form-grid"><input className="inp" placeholder="Tail" value={f.tail} onChange={e=>setF({...f,tail:e.target.value.toUpperCase()})}/><input className="inp" placeholder="Station" value={f.station} onChange={e=>setF({...f,station:e.target.value.toUpperCase()})}/><input className="inp" placeholder="Defect ref" value={f.defectRef} onChange={e=>setF({...f,defectRef:e.target.value})}/><input className="inp" placeholder="WO" value={f.workOrderId} onChange={e=>setF({...f,workOrderId:e.target.value})}/><input className="inp" placeholder="Required part" value={f.requiredPart} onChange={e=>setF({...f,requiredPart:e.target.value})}/><input className="inp" placeholder="Logistics/courier ref" value={f.logisticsRef} onChange={e=>setF({...f,logisticsRef:e.target.value})}/><input className="inp" type="number" min="0" placeholder="Est. cost minor units" value={f.estimatedCostMinor} onChange={e=>setF({...f,estimatedCostMinor:e.target.value})}/><input className="inp" maxLength={3} value={f.currency} onChange={e=>setF({...f,currency:e.target.value.toUpperCase()})}/><textarea className="inp" placeholder="Technical summary" value={f.technicalSummary} onChange={e=>setF({...f,technicalSummary:e.target.value})}/><textarea className="inp" placeholder="Operational impact" value={f.operationalImpact} onChange={e=>setF({...f,operationalImpact:e.target.value})}/></div><button className="btn pri" disabled={!f.tail||!f.defectRef||f.technicalSummary.length<10} onClick={()=>create.mutate()}>Open AOG</button></Card>{(q.data??[]).map(a=>{const x=u[a.id]??{updateType:'TECHNICAL',note:'',status:'',estimatedCostMinor:''};return <Card key={a.id} title={`${a.id} · ${a.tail} · ${a.station}`} meta={a.defectRef}><Pill tone="red">{a.status}</Pill> {a.technicalSummary}<div className="sub">Part {a.requiredPart??'—'} · logistics {a.logisticsRef??'—'} · ETA {zulu(a.recoveryEta)} · cost {(a.estimatedCostMinor/100).toFixed(2)} {a.currency}</div>{a.updates.slice(0,8).map(v=><div className="block" key={v.id}><Pill>{v.updateType}</Pill> {v.note}<div className="sub">{zulu(v.createdAt)}</div></div>)}{a.status!=='CLOSED'&&<div className="row"><select className="inp" value={x.updateType} onChange={e=>setU(m=>({...m,[a.id]:{...x,updateType:e.target.value}}))}>{['TECHNICAL','ENGINEERING','MATERIAL','LOGISTICS','CREW','OPS','RECOVERY'].map(v=><option key={v}>{v}</option>)}</select><input className="inp" placeholder="Update / communication" value={x.note} onChange={e=>setU(m=>({...m,[a.id]:{...x,note:e.target.value}}))}/><input className="inp" type="number" placeholder="Updated cost" value={x.estimatedCostMinor} onChange={e=>setU(m=>({...m,[a.id]:{...x,estimatedCostMinor:e.target.value}}))}/><select className="inp" value={x.status} onChange={e=>setU(m=>({...m,[a.id]:{...x,status:e.target.value}}))}><option value="">Keep status</option>{['OPEN','DIAGNOSIS','MATERIAL','RECOVERY','RTS','CLOSED'].map(v=><option key={v}>{v}</option>)}</select><button className="btn sm" disabled={x.note.length<3} onClick={()=>update.mutate(a.id)}>Update</button></div>}</Card>})}<ErrorNote error={q.error??create.error??update.error}/></div>
}

function Stations({station}:{station:string}){
  const qc=useQueryClient();
  const q=useQuery({queryKey:['mnt','caps',station],queryFn:()=>api<Cap[]>(`/amo/maintenance/station-capabilities${station?`?station=${station}`:''}`)});
  const contracts=useQuery({queryKey:['mnt','contracts'],queryFn:()=>api<Contract[]>('/amo/maintenance/contracts')});
  const [f,setF]=useState({station:station||'ENGM',aircraftType:'A320',maintenanceLevel:'LINE',scope:'Transit checks, defect rectification',limitations:'',authorityRef:'',minimumAuthorizedStaff:'1',requiredToolNos:'',facilities:'Hangar/apron access',effectiveFrom:new Date().toISOString().slice(0,10),effectiveUntil:''});
  const [cf,setCf]=useState({customerRef:'',contractRef:'',stationScope:station||'ENGM',aircraftTypes:'A320',maintenanceLevels:'LINE',responseSlaMinutes:'60',tatSlaHours:'24',effectiveFrom:new Date().toISOString().slice(0,10),effectiveUntil:''});
  const create=useMutation({mutationFn:()=>post('/amo/maintenance/station-capabilities',{station:f.station,aircraftType:f.aircraftType,maintenanceLevel:f.maintenanceLevel,scope:f.scope.split(',').map(x=>x.trim()).filter(Boolean),limitations:f.limitations||null,authorityRef:f.authorityRef,minimumAuthorizedStaff:Number(f.minimumAuthorizedStaff),requiredToolNos:f.requiredToolNos.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),facilities:f.facilities.split(',').map(x=>x.trim()).filter(Boolean),effectiveFrom:f.effectiveFrom,effectiveUntil:f.effectiveUntil||null}),onSuccess:()=>refresh(qc)});
  const state=useMutation({mutationFn:(x:{id:string;active:boolean})=>post(`/amo/maintenance/station-capabilities/${x.id}/state`,{active:x.active,reason:x.active?'Authorized capability restoration':'Authorized capability suspension'}),onSuccess:()=>refresh(qc)});
  const createContract=useMutation({mutationFn:()=>post('/amo/maintenance/contracts',{customerRef:cf.customerRef,contractRef:cf.contractRef,stationScope:cf.stationScope.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),aircraftTypes:cf.aircraftTypes.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),maintenanceLevels:cf.maintenanceLevels.split(',').map(x=>x.trim()).filter(Boolean),responseSlaMinutes:cf.responseSlaMinutes?Number(cf.responseSlaMinutes):null,tatSlaHours:cf.tatSlaHours?Number(cf.tatSlaHours):null,rateCard:{},effectiveFrom:cf.effectiveFrom,effectiveUntil:cf.effectiveUntil||null}),onSuccess:()=>refresh(qc)});
  const contractState=useMutation({mutationFn:(x:{id:string;active:boolean})=>post(`/amo/maintenance/contracts/${x.id}/state`,{active:x.active,reason:x.active?'Contract restored after authorized review':'Contract suspended by authorized maintenance control'}),onSuccess:()=>refresh(qc)});
  return <div className="stack">
    <Card title="Approve station capability"><div className="form-grid"><input className="inp" value={f.station} onChange={e=>setF({...f,station:e.target.value.toUpperCase()})}/><input className="inp" value={f.aircraftType} onChange={e=>setF({...f,aircraftType:e.target.value.toUpperCase()})}/><select className="inp" value={f.maintenanceLevel} onChange={e=>setF({...f,maintenanceLevel:e.target.value})}>{['TRANSIT','LINE','BASE','ENGINE_CHANGE','AOG','SHOP_SUPPORT'].map(x=><option key={x}>{x}</option>)}</select><input className="inp" placeholder="Scope (comma separated)" value={f.scope} onChange={e=>setF({...f,scope:e.target.value})}/><input className="inp" placeholder="Authority/MOE ref" value={f.authorityRef} onChange={e=>setF({...f,authorityRef:e.target.value})}/><input className="inp" type="number" min="0" placeholder="Min authorised staff" value={f.minimumAuthorizedStaff} onChange={e=>setF({...f,minimumAuthorizedStaff:e.target.value})}/><input className="inp" placeholder="Required tool numbers" value={f.requiredToolNos} onChange={e=>setF({...f,requiredToolNos:e.target.value})}/><input className="inp" placeholder="Facilities" value={f.facilities} onChange={e=>setF({...f,facilities:e.target.value})}/><input className="inp" type="date" value={f.effectiveFrom} onChange={e=>setF({...f,effectiveFrom:e.target.value})}/><input className="inp" type="date" value={f.effectiveUntil} onChange={e=>setF({...f,effectiveUntil:e.target.value})}/></div><button className="btn pri" disabled={!f.authorityRef} onClick={()=>create.mutate()}>Approve</button></Card>
    <Card title="Capability register"><table className="t"><thead><tr><th>Station</th><th>Aircraft / level</th><th>Capability</th><th>Resources</th><th>Approval</th><th>State</th></tr></thead><tbody>{(q.data??[]).map(c=><tr key={c.id}><td>{c.station}</td><td>{c.aircraftType}<div className="sub">{c.maintenanceLevel}</div></td><td>{c.scope.join(', ')}</td><td>{c.minimumAuthorizedStaff} authorised staff<div className="sub">tools {c.requiredToolNos.join(', ')||'—'} · facilities {c.facilities.join(', ')||'—'}</div></td><td>{c.authorityRef}<div className="sub">{c.effectiveFrom} → {c.effectiveUntil??'open'}</div></td><td><Pill tone={c.active?'green':'red'}>{c.active?'ACTIVE':'SUSPENDED'}</Pill><button className="btn sm" onClick={()=>state.mutate({id:c.id,active:!c.active})}>{c.active?'Suspend':'Activate'}</button></td></tr>)}</tbody></table></Card>
    <Card title="Maintenance contracts & SLA"><div className="form-grid"><input className="inp" placeholder="Customer" value={cf.customerRef} onChange={e=>setCf({...cf,customerRef:e.target.value})}/><input className="inp" placeholder="Contract ref" value={cf.contractRef} onChange={e=>setCf({...cf,contractRef:e.target.value})}/><input className="inp" placeholder="Stations" value={cf.stationScope} onChange={e=>setCf({...cf,stationScope:e.target.value})}/><input className="inp" placeholder="Aircraft types" value={cf.aircraftTypes} onChange={e=>setCf({...cf,aircraftTypes:e.target.value})}/><input className="inp" placeholder="Levels (LINE,BASE...)" value={cf.maintenanceLevels} onChange={e=>setCf({...cf,maintenanceLevels:e.target.value})}/><input className="inp" type="number" placeholder="Response SLA min" value={cf.responseSlaMinutes} onChange={e=>setCf({...cf,responseSlaMinutes:e.target.value})}/><input className="inp" type="number" placeholder="TAT SLA hours" value={cf.tatSlaHours} onChange={e=>setCf({...cf,tatSlaHours:e.target.value})}/><input className="inp" type="date" value={cf.effectiveFrom} onChange={e=>setCf({...cf,effectiveFrom:e.target.value})}/></div><button className="btn pri" disabled={!cf.customerRef||!cf.contractRef} onClick={()=>createContract.mutate()}>Approve contract</button><table className="t"><thead><tr><th>Customer</th><th>Contract</th><th>Scope</th><th>SLA</th><th>State</th></tr></thead><tbody>{(contracts.data??[]).map(c=><tr key={c.id}><td>{c.customerRef}</td><td>{c.contractRef}</td><td>{c.stationScope.join(', ')} · {c.aircraftTypes.join(', ')}<div className="sub">{c.maintenanceLevels.join(', ')}</div></td><td>{c.responseSlaMinutes??'—'} min response · {c.tatSlaHours??'—'} h TAT</td><td><Pill tone={c.active?'green':'red'}>{c.active?'ACTIVE':'SUSPENDED'}</Pill><button className="btn sm" onClick={()=>contractState.mutate({id:c.id,active:!c.active})}>{c.active?'Suspend':'Activate'}</button></td></tr>)}</tbody></table></Card>
    <ErrorNote error={q.error??contracts.error??create.error??state.error??createContract.error??contractState.error}/>
  </div>
}
